Writing your Own Method - O(n) Time and O(1) SpaceIf their lengths are the same. If the lengths differ, the strings cannot be identical, so it returns false. Then compares each character of the two strings one by one. If any mismatch is found, it returns false.If no differences are found throughout the comparison, it returns true.
            C++

    #include <iostream>
using namespace std;

bool areStringsEqual(string &s1, string &s2) {

    // Compare lengths first
    if (s1.length() != s2.length()) {
        return false;
    }

    // Compare character by character
    for (size_t i = 0; i < s1.length(); ++i) {
        if (s1[i] != s2[i]) {
            return false; 
        }
    }

    return true; 
}

int main() {
    string s1 = "hello";
    string s2 = "hello";

    if (areStringsEqual(s1, s2)) {
        cout << "Yes" << endl; 
    } else {
        cout << "No" << endl;  
    }

    return 0;
}


