    #include <stdio.h>
#include <string.h>
#include <stdbool.h>

bool areStringsEqual(const char *s1, const char *s2) {
    // Compare lengths first
    if (strlen(s1) != strlen(s2)) {
        return 0;
    }

    // Compare character by character
    for (size_t i = 0; i < strlen(s1); ++i) {
        if (s1[i] != s2[i]) {
            return 0;
        }
    }

    return 1;
}

int main() {
    const char *s1 = "hello";
    const char *s2 = "hello";

    if (areStringsEqual(s1, s2)) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }

    return 0;
}


